        ("turkey", "tr"), ("france", "fr"), ("spain", "es"), ("italy", "it"),
        ("germany", "de"), ("portugal", "pt"), ("russia", "ru"),
        ("greece", "el"), ("dutch", "de"), ("nederlands", "de"),
        ("malaysia", "id"), ("malay", "id"), ("singapore", "zh")
